/**
 * UniverseTime: A singleton managing the simulated flow of time.
 * This allows for deterministic simulations and time-based event triggers.
 */
const UniverseTime = (() => {
    let currentTime = new Date('2042-08-15T10:30:00Z').getTime();
    const tickRateMs = 100; // Each real-time 100ms is one hour in simulation.
    const tickIncrement = 60 * 60 * 1000;
    let subscribers: ((time: number) => void)[] = [];
    let intervalId: any = null;

    const start = () => {
        if (intervalId) return;
        intervalId = setInterval(() => {
            currentTime += tickIncrement;
            subscribers.forEach(cb => cb(currentTime));
        }, tickRateMs);
    };

    const stop = () => {
        if (intervalId) {
            clearInterval(intervalId);
            intervalId = null;
        }
    };

    return {
        now: () => new Date(currentTime),
        nowISO: () => new Date(currentTime).toISOString(),
        nowMs: () => currentTime,
        subscribe: (callback: (time: number) => void) => {
            subscribers.push(callback);
            return () => {
                subscribers = subscribers.filter(cb => cb !== callback);
            };
        },
        start,
        stop,
        set: (isoString: string) => {
            currentTime = new Date(isoString).getTime();
            subscribers.forEach(cb => cb(currentTime));
        },
        advance: (ms: number) => {
            currentTime += ms;
            subscribers.forEach(cb => cb(currentTime));
        }
    };
})();
UniverseTime.start();

/**
 * QuantumEventManager: A universe-wide pub/sub system for decoupled communication.
 * All major events (security breaches, regulatory changes, market shifts) are broadcast through this bus.
 */
const QuantumEventManager = (() => {
    const topics: { [key: string]: Function[] } = {};

    return {
        publish: (topic: string, data: any) => {
            if (!topics[topic]) return;
            topics[topic].forEach(callback => {
                try {
                    callback(data);
                } catch (error) {
                    console.error(`Error in event handler for topic ${topic}:`, error);
                }
            });
        },
        subscribe: (topic: string, callback: Function) => {
            if (!topics[topic]) {
                topics[topic] = [];
            }
            topics[topic].push(callback);
            return () => {
                topics[topic] = topics[topic].filter(cb => cb !== callback);
            };
        },
    };
})();

/**
 * EntropyGenerator: Provides seeded, deterministic randomness for the simulation.
 * Ensures that simulations can be replayed if necessary.
 */
const EntropyGenerator = (seed: number) => {
    let currentSeed = seed;
    return {
        next: () => {
            currentSeed = (currentSeed * 9301 + 49297) % 233280;
            return currentSeed / 233280;
        },
        nextInt: (min: number, max: number) => {
            return Math.floor(min + (max - min + 1) * this.next());
        },
        select: <T,>(arr: T[]): T => {
            return arr[Math.floor(this.next() * arr.length)];
        },
    };
};
const globalEntropy = EntropyGenerator(42);


