type Scene = 'dashboard' | 'developer_portal' | 'regulatory_console' | 'api_explorer';

const SceneManager: FC<{ activeScene: Scene; state: UniverseState; dispatch: React.Dispatch<UniverseAction> }> = ({ activeScene, state, dispatch }) => {
    switch (activeScene) {
        case 'dashboard':
            // This would contain the main OpenBankingView logic, but vastly expanded
            return <div>Dashboard Scene Content</div>;
        case 'developer_portal':
            return <div>Developer Portal Scene Content</div>;
        case 'regulatory_console':
            return <div>Regulatory Console Scene Content</div>;
        case 'api_explorer':
            return <ApiExplorerScene />;
        default:
            return <div>Unknown Scene</div>;
    }
};

const ApiExplorerScene: FC = () => {
    const [selectedApi, setSelectedApi] = useState(Object.keys(api)[0]);
    const [selectedEndpoint, setSelectedEndpoint] = useState('');
    const [params, setParams] = useState('{}');
    const [response, setResponse] = useState<any>(null);
    const [isLoading, setIsLoading] = useState(false);

    const handleApiChange = (apiName: string) => {
        setSelectedApi(apiName);
        setSelectedEndpoint('');
        setResponse(null);
    };

    const handleRun = async () => {
        setIsLoading(true);
        try {
            const parsedParams = JSON.parse(params);
            const apiModule = (api as any)[selectedApi];
            const res = await apiModule.call(selectedEndpoint, parsedParams, `valid-token-for-${apiModule._name.toLowerCase().replace(/ /g, '-')}`);
            setResponse(res);
        } catch (e) {
            setResponse({ status: 500, error: 'Invalid JSON in params.' });
        }
        setIsLoading(false);
    };

    return (
        <QCard title="Universe API Explorer">
            <div className="grid grid-cols-3 gap-4">
                <div>
                    <label>Select API</label>
                    <select value={selectedApi} onChange={e => handleApiChange(e.target.value)} className="w-full p-2 bg-gray-700 rounded">
                        {Object.keys(api).map(name => <option key={name} value={name}>{name}</option>)}
                    </select>
                </div>
                <div>
                    <label>Select Endpoint</label>
                    <select value={selectedEndpoint} onChange={e => setSelectedEndpoint(e.target.value)} className="w-full p-2 bg-gray-700 rounded" disabled={!selectedApi}>
                        <option value="">--</option>
                        {/* This is a simplification; a real implementation would inspect the module */}
                        {selectedApi && Object.keys((api as any)[selectedApi].call.__closure__.config.endpoints).map(ep => <option key={ep} value={ep}>{ep}</option>)}
                    </select>
                </div>
            </div>
            <div className="mt-4">
                <label>Params (JSON)</label>
                <textarea value={params} onChange={e => setParams(e.target.value)} className="w-full p-2 bg-gray-700 rounded font-mono h-24"></textarea>
            </div>
            <QButton onClick={handleRun} disabled={!selectedEndpoint || isLoading}>
                {isLoading ? <QSpinner size="sm" /> : 'Run'}
            </QButton>
            {response && (
                <div className="mt-4">
                    <h4 className="font-bold">Response</h4>
                    <pre className="p-2 bg-gray-900 rounded text-xs overflow-auto">
                        {JSON.stringify(response, null, 2)}
                    </pre>
                </div>
            )}
        </QCard>
    );
};

